func (q *Queries) UpsertProfile(ctx context.Context, arg *UpsertProfileParams) (*UpsertProfileRow, error) {
	row := q.db.QueryRow(ctx, upsertProfile, arg.UserID, arg.Handle, arg.DisplayName)
	var i UpsertProfileRow
	err := row.Scan(&i.UserID, &i.Handle, &i.DisplayName)
	return &i, err
}
